/* the box of a passive */
.aa-tree-ptip {
  box-sizing: border-box;
  width: 300px;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  line-height: 1.5;
}
.aa-tree-phead {
  display: flex;
  gap: 10px;
  align-items: center;
}
.aa-tree-picon img {
  display: block;
  width: 40px;
  height: 40px;
}
.aa-tree-pkind {
  color: #bdb6a4;
  font-size: 12px;
}
.aa-tree-pname {
  color: #fff;
  font-size: 15px;
  font-weight: bold;
}
.aa-tree-sep {
  height: 0;
  margin: 7px 0;
  border-top: 1px solid #3c3a36;
}
.aa-tree-ptext {
  color: #e8e4d8;
}

/* the watermark at the bottom of the tree: laid over the bottom edge, so the tree does not get taller; it sits in
   the free space beside the single Abyssal passive */
.aa-tree-mark {
  position: absolute;
  bottom: 19px;
  left: 50%;
  margin: 0 0 0 -30px;
  line-height: 0;
  opacity: 0.7;
  pointer-events: none;
}
.aa-tree-mark img {
  display: block;
}
